public class Book
{
    public string ISBN { get; }
    public string Title { get; }
    public string Author { get; }
    public bool IsAvailable { get; private set; } = true;
    public DateTime? DueDate { get; private set; }
}

public class Member
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public List<Book> BorrowedBooks { get; } = new();
    public int BorrowLimit => 5;
}

public class LibraryService
{
    private readonly Dictionary<string, Book> _books = new();
    private readonly Dictionary<Guid, Member> _members = new();

    public void AddBook(Book book) => _books[book.ISBN] = book;

    public Book? Search(string query) =>
        _books.Values.FirstOrDefault(b =>
            b.Title.Contains(query, StringComparison.OrdinalIgnoreCase) ||
            b.Author.Contains(query, StringComparison.OrdinalIgnoreCase));

    public void Checkout(string isbn, Guid memberId)
    {
        var book = _books[isbn];
        var member = _members[memberId];
        if (!book.IsAvailable) throw new InvalidOperationException("Checked out");
        if (member.BorrowedBooks.Count >= member.BorrowLimit) throw new InvalidOperationException("Limit reached");
        book.IsAvailable = false;
        book.DueDate = DateTime.UtcNow.AddDays(14);
        member.BorrowedBooks.Add(book);
    }

    public decimal Return(string isbn, Guid memberId)
    {
        var book = _books[isbn];
        var member = _members[memberId];
        member.BorrowedBooks.Remove(book);
        book.IsAvailable = true;
        if (DateTime.UtcNow > book.DueDate)
        {
            var daysLate = (DateTime.UtcNow - book.DueDate.Value).Days;
            book.DueDate = null;
            return daysLate * 0.5m; // 50 cents per day
        }
        book.DueDate = null;
        return 0;
    }
}
